python3 - <<'PY'
from pydantic import BaseModel, Field, ValidationError

class Model(BaseModel):
    x: int = Field(validation_alias=None)

try:
    Model.model_validate({'x': 1})
    print("Success with x")
except ValidationError as e:
    print(f"Error with x: {e}")

try:
    Model.model_validate({'my_alias': 1})
    print("Success with my_alias")
except ValidationError as e:
    print(f"Error with my_alias: {e}")
